1	package oci
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net/http"
9		"net/http/httptest"
10		"net/url"
11		"strings"
12		"sync/atomic"
13		"testing"
14		"testing/iotest"
15	)
16	
17	// DEVDESK-412 step 2: the shared guards DEVDESK-410 introduced are exported so
18	// the other registry HTTP clients can use them, the redirect cap no longer
19	// carries the last target URL, and the bounded-read and URL-redaction helpers
20	// exist.
21	
22	// A registry that redirects forever to a signed URL must end in
23	// ErrTooManyRedirects, with the cap in the text and nothing of the last
24	// target (its path and signed query) in the error.
25	func TestRegistryRedirectLimitCarriesNoTarget(t *testing.T) {
26		var hops atomic.Int32
27		s := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
28			n := hops.Add(1)
29			http.Redirect(w, r, fmt.Sprintf("/hop%d-SECRET?sig=SECRET", n), http.StatusFound)
30		}))
31		defer s.Close()
32	
33		_, err := ListRegistryTagsContext(context.Background(), s.URL, "x", "user", "pass")
34		if err == nil {
35			t.Fatal("err = nil, want the redirect cap")
36		}
37		if !errors.Is(err, ErrTooManyRedirects) {
38			t.Errorf("err = %v, want errors.Is(err, ErrTooManyRedirects)", err)
39		}
40		if !strings.Contains(err.Error(), "stopped after 10 redirects") {
41			t.Errorf("err = %q, want it to contain %q", err, "stopped after 10 redirects")
42		}
43		for _, leak := range []string{"SECRET", "sig=", "/hop"} {
44			if strings.Contains(err.Error(), leak) {
45				t.Errorf("error %q leaks %q from the last redirect target", err, leak)
46			}
47		}
48		// Same count as 410: the original request plus nine followed redirects.
49		if got := hops.Load(); got != 10 {
50			t.Errorf("server saw %d requests, want 10", got)
51		}
52	}
