54	// endlessReader yields 'a' forever and counts what was taken from it.
55	type endlessReader struct{ read int64 }
56	
57	func (r *endlessReader) Read(p []byte) (int, error) {
58		for i := range p {
59			p[i] = 'a'
60		}
61		r.read += int64(len(p))
62		return len(p), nil
63	}
