65	func TestReadAllLimited(t *testing.T) {
66		const limit = 8
67		boom := errors.New("connection reset")
68	
69		tests := []struct {
70			name    string
71			r       io.Reader
72			limit   int64
73			want    string
74			wantErr error  // matched with errors.Is when non-nil
75			wantMsg string // substring of the error text
76		}{
77			{name: "empty", r: strings.NewReader(""), limit: limit, want: ""},
78			{name: "limit minus one", r: strings.NewReader(strings.Repeat("a", limit-1)), limit: limit, want: strings.Repeat("a", limit-1)},
79			{name: "exactly the limit is accepted", r: strings.NewReader(strings.Repeat("a", limit)), limit: limit, want: strings.Repeat("a", limit)},
80			{
81				name: "limit plus one is refused", r: strings.NewReader(strings.Repeat("a", limit+1)), limit: limit,
82				wantErr: ErrBodyTooLarge, wantMsg: "response body over 8 bytes",
83			},
84			{
85				name: "far over the limit is refused", r: strings.NewReader(strings.Repeat("a", 10*limit)), limit: limit,
86				wantErr: ErrBodyTooLarge, wantMsg: "response body over 8 bytes",
87			},
88			{
89				name: "reader error is returned, not mistaken for size", r: iotest.ErrReader(boom), limit: limit,
90				wantErr: boom,
91			},
92			{
93				name: "reader error after some bytes", r: io.MultiReader(strings.NewReader("abc"), iotest.ErrReader(boom)), limit: limit,
94				wantErr: boom,
95			},
96		}
97		for _, tc := range tests {
98			t.Run(tc.name, func(t *testing.T) {
99				got, err := ReadAllLimited(tc.r, tc.limit)
100				if tc.wantErr != nil {
101					if !errors.Is(err, tc.wantErr) {
102						t.Fatalf("err = %v, want errors.Is %v", err, tc.wantErr)
103					}
104					if tc.wantMsg != "" && !strings.Contains(err.Error(), tc.wantMsg) {
105						t.Errorf("err = %q, want it to contain %q", err, tc.wantMsg)
106					}
107					if !errors.Is(tc.wantErr, ErrBodyTooLarge) && errors.Is(err, ErrBodyTooLarge) {
108						t.Errorf("err = %v, a reader error must not read as ErrBodyTooLarge", err)
109					}
110					return
111				}
112				if err != nil {
113					t.Fatalf("err = %v, want nil", err)
114				}
115				if string(got) != tc.want {
116					t.Errorf("got %q, want %q", got, tc.want)
117				}
118			})
119		}
120	
121		t.Run("an endless reader stops one byte past the limit", func(t *testing.T) {
122			r := &endlessReader{}
123			_, err := ReadAllLimited(r, limit)
124			if !errors.Is(err, ErrBodyTooLarge) {
125				t.Fatalf("err = %v, want ErrBodyTooLarge", err)
126			}
127			if r.read > limit+1 {
128				t.Errorf("took %d bytes from the reader, want at most %d", r.read, limit+1)
129			}
130		})
131	}
