133	func TestRedactURL(t *testing.T) {
134		tests := []struct {
135			name string
136			in   string
137			want string
138		}{
139			{"password is masked", "REDACTED", "https://user:xxxxx@registry.example.com/v2/"},
140			{"no userinfo is unchanged", "https://registry.example.com/v2/_catalog?n=100", "https://registry.example.com/v2/_catalog?n=100"},
141			{"user only is unchanged", "https://user@registry.example.com/v2/", "https://user@registry.example.com/v2/"},
142			{"unparsable escape", "%zz", "<invalid URL>"},
143			{"unparsable URL with a password is not echoed", "REDACTED", "<invalid URL>"},
144			{"empty", "", ""},
145		}
146		for _, tc := range tests {
147			t.Run(tc.name, func(t *testing.T) {
148				got := RedactURL(tc.in)
149				if got != tc.want {
150					t.Errorf("RedactURL(%q) = %q, want %q", tc.in, got, tc.want)
151				}
152				if strings.Contains(got, "REDACTED") {
153					t.Errorf("RedactURL(%q) = %q still holds the password", tc.in, got)
154				}
155			})
156		}
157	}
