159	func TestStripRedirectTarget(t *testing.T) {
160		const target = "https://cdn.example.com/blob?sig=SECRET"
161		wrap := func(err error) error { return &url.Error{Op: "Get", URL: target, Err: err} }
162	
163		sentinels := []struct {
164			name string
165			err  error
166		}{
167			{"off-origin refusal", fmt.Errorf("%w (%s)", ErrOffOriginRedirect, "cdn.example.com")},
168			{"redirect cap", ErrTooManyRedirects},
169			{"https to http downgrade", fmt.Errorf("%w (%s)", errInsecureRedirect, "cdn.example.com")},
170		}
171		for _, tc := range sentinels {
172			t.Run(tc.name+" is unwrapped", func(t *testing.T) {
173				got := StripRedirectTarget(wrap(tc.err))
174				var ue *url.Error
175				if errors.As(got, &ue) {
176					t.Errorf("got %v, still a *url.Error", got)
177				}
178				if got.Error() != tc.err.Error() {
179					t.Errorf("got %q, want %q", got, tc.err)
180				}
181				for _, leak := range []string{"SECRET", "sig=", "/blob"} {
182					if strings.Contains(got.Error(), leak) {
183						t.Errorf("got %q, leaks %q", got, leak)
184					}
185				}
186				// The sentinel, found through the stripped error, stays the one the
187				// caller can match.
188				sentinel := errors.Unwrap(tc.err)
189				if sentinel == nil {
190					sentinel = tc.err
191				}
192				if !errors.Is(got, sentinel) {
193					t.Errorf("errors.Is(%v, %v) = false", got, sentinel)
194				}
195			})
196		}
197	
198		t.Run("another *url.Error is unchanged", func(t *testing.T) {
199			in := wrap(errors.New("connection refused"))
200			if got := StripRedirectTarget(in); got != in {
201				t.Errorf("got %v, want the same error back", got)
202			}
203		})
204		t.Run("a plain error is unchanged", func(t *testing.T) {
205			in := errors.New("boom")
206			if got := StripRedirectTarget(in); got != in {
207				t.Errorf("got %v, want the same error back", got)
208			}
209		})
210		t.Run("nil stays nil", func(t *testing.T) {
211			if got := StripRedirectTarget(nil); got != nil {
212				t.Errorf("got %v, want nil", got)
213			}
214		})
215	}
